import{_ as o,o as e,c as a,a2 as i}from"./chunks/framework.D7WGirly.js";const p=JSON.parse('{"title":"Copilot — Troubleshooting & FAQs","description":"","frontmatter":{},"headers":[],"relativePath":"copilot-04-troubleshooting-and-faqs.md","filePath":"copilot-04-troubleshooting-and-faqs.md"}'),r={name:"copilot-04-troubleshooting-and-faqs.md"};function n(s,t,l,h,c,d){return e(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="copilot-—-troubleshooting-faqs" tabindex="-1">Copilot — Troubleshooting &amp; FAQs <a class="header-anchor" href="#copilot-—-troubleshooting-faqs" aria-label="Permalink to &quot;Copilot — Troubleshooting &amp; FAQs&quot;">​</a></h1><p><em>Common questions and what to do when things don&#39;t work as expected</em></p><hr><h2 id="who-can-use-copilot" tabindex="-1">Who can use Copilot? <a class="header-anchor" href="#who-can-use-copilot" aria-label="Permalink to &quot;Who can use Copilot?&quot;">​</a></h2><p>All workspace members — both Admins and Builders — have access to Copilot. It is available from every page in Lodestone.</p><hr><h2 id="copilot-created-the-wrong-feature-took-the-wrong-action-what-do-i-do" tabindex="-1">Copilot created the wrong feature / took the wrong action. What do I do? <a class="header-anchor" href="#copilot-created-the-wrong-feature-took-the-wrong-action-what-do-i-do" aria-label="Permalink to &quot;Copilot created the wrong feature / took the wrong action. What do I do?&quot;">​</a></h2><p>Copilot respects the same permissions as your account but does not have an undo button. If it creates something incorrectly, you can:</p><ul><li>Ask it to fix it: &quot;Update that feature name to X&quot; or &quot;Change the status to Not Started&quot;</li><li>Navigate to the object directly and edit it manually in the normal UI</li></ul><p>For anything Copilot cannot undo (like a mistaken creation you want removed), delete the object from the standard backlog or roadmap UI.</p><hr><h2 id="copilot-isn-t-finding-the-right-feature-when-i-ask-it-to-act-on-one" tabindex="-1">Copilot isn&#39;t finding the right feature when I ask it to act on one. <a class="header-anchor" href="#copilot-isn-t-finding-the-right-feature-when-i-ask-it-to-act-on-one" aria-label="Permalink to &quot;Copilot isn&#39;t finding the right feature when I ask it to act on one.&quot;">​</a></h2><p>If your workspace has multiple features with similar names, Copilot may ask for clarification or act on the wrong one. The most reliable way to reference a specific feature is to use its feature key (e.g. FEAT-7) instead of a partial name.</p><p>You can ask Copilot to list features first: &quot;List features with &#39;auth&#39; in the name&quot; — then use the key from the results in your next instruction.</p><hr><h2 id="copilot-answered-my-question-incorrectly-or-gave-outdated-information" tabindex="-1">Copilot answered my question incorrectly or gave outdated information. <a class="header-anchor" href="#copilot-answered-my-question-incorrectly-or-gave-outdated-information" aria-label="Permalink to &quot;Copilot answered my question incorrectly or gave outdated information.&quot;">​</a></h2><p>Copilot&#39;s knowledge base is periodically updated to reflect changes to the platform. If you receive incorrect information about Lodestone:</p><ul><li>Try rephrasing the question</li><li>Check the relevant help documentation directly</li><li>If the answer seems significantly wrong, it may indicate the knowledge base hasn&#39;t been updated yet for a recent feature</li></ul><p>For questions about your own workspace data (features, roadmaps, etc.), Copilot reads live from your workspace, so that information is always current.</p><hr><h2 id="i-asked-copilot-to-do-something-but-it-just-answered-my-question-instead" tabindex="-1">I asked Copilot to do something but it just answered my question instead. <a class="header-anchor" href="#i-asked-copilot-to-do-something-but-it-just-answered-my-question-instead" aria-label="Permalink to &quot;I asked Copilot to do something but it just answered my question instead.&quot;">​</a></h2><p>Copilot classifies intent based on your message. If your request reads more like a question than an instruction, it defaults to Chatbot mode.</p><p>Try rephrasing as a clear instruction:</p><ul><li><p>Instead of: &quot;Can you make a feature called SSO?&quot;</p></li><li><p>Try: &quot;Create a feature called SSO&quot;</p></li><li><p>Instead of: &quot;Is there a way to add this to my roadmap?&quot;</p></li><li><p>Try: &quot;Add this feature to my Q3 Roadmap&quot;</p></li></ul><hr><h2 id="copilot-is-returning-a-rate-limit-error" tabindex="-1">Copilot is returning a rate limit error. <a class="header-anchor" href="#copilot-is-returning-a-rate-limit-error" aria-label="Permalink to &quot;Copilot is returning a rate limit error.&quot;">​</a></h2><p>Copilot is rate-limited per user. If you&#39;ve sent many messages in a short time, wait a minute and try again. This resolves automatically — no page reload is needed.</p><hr><h2 id="i-lost-my-conversation-history-what-happened" tabindex="-1">I lost my conversation history. What happened? <a class="header-anchor" href="#i-lost-my-conversation-history-what-happened" aria-label="Permalink to &quot;I lost my conversation history. What happened?&quot;">​</a></h2><p>Conversation history is stored locally in your browser and expires. Once a conversation expires, it is gone — it is not recoverable from the server. Starting a fresh conversation is the only option.</p><p>This is intentional: conversation history is session context, not a permanent record. Use Copilot for in-the-moment tasks, not as a log of past actions.</p><hr><h2 id="can-copilot-access-my-quotes-evaluation-scores-or-financial-models" tabindex="-1">Can Copilot access my quotes, evaluation scores, or financial models? <a class="header-anchor" href="#can-copilot-access-my-quotes-evaluation-scores-or-financial-models" aria-label="Permalink to &quot;Can Copilot access my quotes, evaluation scores, or financial models?&quot;">​</a></h2><p>Not currently. Copilot&#39;s workspace access is limited to backlog items (name, status, description, key), roadmaps, releases, and strategies. It does not have access to customer quotes, RICE scores, custom evaluation fields, or Financial Forecast data.</p><p>If you need to act on those objects, use the relevant module directly.</p><hr><h2 id="can-copilot-take-actions-in-jira-or-other-external-tools" tabindex="-1">Can Copilot take actions in JIRA or other external tools? <a class="header-anchor" href="#can-copilot-take-actions-in-jira-or-other-external-tools" aria-label="Permalink to &quot;Can Copilot take actions in JIRA or other external tools?&quot;">​</a></h2><p>No. Copilot operates only within Lodestone. It does not have access to external tools, even if you have integrations connected (JIRA, Gong, Fireflies, etc.). Actions taken through Copilot in Lodestone will sync to JIRA in the normal way if the JIRA integration is active.</p><hr><h2 id="does-copilot-delete-things" tabindex="-1">Does Copilot delete things? <a class="header-anchor" href="#does-copilot-delete-things" aria-label="Permalink to &quot;Does Copilot delete things?&quot;">​</a></h2><p>Copilot cannot delete features, roadmaps, releases, or any other objects. If you ask it to delete something, it will tell you it can&#39;t and suggest how to do it manually.</p><hr><h2 id="is-there-a-limit-to-what-i-can-create-through-copilot" tabindex="-1">Is there a limit to what I can create through Copilot? <a class="header-anchor" href="#is-there-a-limit-to-what-i-can-create-through-copilot" aria-label="Permalink to &quot;Is there a limit to what I can create through Copilot?&quot;">​</a></h2><p>No separate limit applies to objects created through Copilot. The same workspace limits that apply to your account apply regardless of how objects are created.</p><hr>',45)])])}const m=o(r,[["render",n]]);export{p as __pageData,m as default};
